SELECT COUNT(*) FROM badges as b, comments as c, postHistory as ph, users as u, posts as p WHERE c.UserId = u.Id AND b.UserId = u.Id AND p.Id = c.PostId AND p.Id = ph.PostId AND c.CreationDate>='2010-07-22 01:19:43'::timestamp AND ph.CreationDate>='2010-09-20 17:45:15'::timestamp AND ph.CreationDate<='2014-08-07 01:00:45'::timestamp;